import Foundation

/// The update feed (`feed.json`, generated by `scripts/feed.mjs`). Built apps carry a
/// version, checksum and download; planned apps carry only their name and pitch.
public struct Feed: Codable, Sendable, Equatable {
    public var schemaVersion: Int
    public var generatedAt: Date?
    public var apps: [FeedApp]

    public init(schemaVersion: Int = 1, generatedAt: Date? = nil, apps: [FeedApp]) {
        self.schemaVersion = schemaVersion
        self.generatedAt = generatedAt
        self.apps = apps
    }

    /// The newest schema this launcher understands. Newer feeds are refused rather than misread.
    public static let supportedSchema = 1
}

public struct FeedApp: Codable, Sendable, Equatable, Identifiable, Hashable {
    public var slug: String
    public var name: String
    public var tagline: String
    public var category: String?
    public var replaces: [String]
    public var menuBarOnly: Bool?
    public var hub: Bool?
    public var status: String?
    // Present only for built, released apps:
    public var version: String?
    public var build: Int?
    public var minimumMacOS: String?
    public var bundleId: String?
    public var downloadUrl: URL?
    public var iconUrl: URL?
    public var sha256: String?
    public var size: Int64?
    public var installedSize: Int64?
    public var releaseNotes: String?
    /// Store screenshots (beta and later apps with a set). Empty when there are none.
    public var shots: [FeedShot]
    /// Changes whenever the set is retaken ("<app version>-<showcase version>").
    public var shotsVersion: String?

    public var id: String { slug }

    public init(
        slug: String, name: String, tagline: String, category: String? = nil, replaces: [String] = [],
        menuBarOnly: Bool? = nil, hub: Bool? = nil, status: String? = nil, version: String? = nil,
        build: Int? = nil, minimumMacOS: String? = nil, bundleId: String? = nil, downloadUrl: URL? = nil,
        iconUrl: URL? = nil, sha256: String? = nil, size: Int64? = nil, installedSize: Int64? = nil,
        releaseNotes: String? = nil, shots: [FeedShot] = [], shotsVersion: String? = nil
    ) {
        self.slug = slug
        self.name = name
        self.tagline = tagline
        self.category = category
        self.replaces = replaces
        self.menuBarOnly = menuBarOnly
        self.hub = hub
        self.status = status
        self.version = version
        self.build = build
        self.minimumMacOS = minimumMacOS
        self.bundleId = bundleId
        self.downloadUrl = downloadUrl
        self.iconUrl = iconUrl
        self.sha256 = sha256
        self.size = size
        self.installedSize = installedSize
        self.releaseNotes = releaseNotes
        self.shots = shots
        self.shotsVersion = shotsVersion
    }

    enum CodingKeys: String, CodingKey {
        case slug, name, tagline, category, replaces, menuBarOnly, hub, status, version, build
        case minimumMacOS, bundleId, downloadUrl, iconUrl, sha256, size, installedSize, releaseNotes
        case shots, shotsVersion
    }

    public init(from decoder: any Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        slug = try c.decode(String.self, forKey: .slug)
        name = try c.decode(String.self, forKey: .name)
        tagline = try c.decodeIfPresent(String.self, forKey: .tagline) ?? ""
        category = try c.decodeIfPresent(String.self, forKey: .category)
        replaces = try c.decodeIfPresent([String].self, forKey: .replaces) ?? []
        menuBarOnly = try c.decodeIfPresent(Bool.self, forKey: .menuBarOnly)
        hub = try c.decodeIfPresent(Bool.self, forKey: .hub)
        status = try c.decodeIfPresent(String.self, forKey: .status)
        version = try c.decodeIfPresent(String.self, forKey: .version)
        build = try c.decodeIfPresent(Int.self, forKey: .build)
        minimumMacOS = try c.decodeIfPresent(String.self, forKey: .minimumMacOS)
        bundleId = try c.decodeIfPresent(String.self, forKey: .bundleId)
        // URLs may be relative to the feed (local test feeds use "Awake.zip").
        downloadUrl = try c.decodeIfPresent(String.self, forKey: .downloadUrl).flatMap(Self.resolve(decoder))
        iconUrl = try c.decodeIfPresent(String.self, forKey: .iconUrl).flatMap(Self.resolve(decoder))
        sha256 = try c.decodeIfPresent(String.self, forKey: .sha256)?.lowercased()
        size = try c.decodeIfPresent(Int64.self, forKey: .size)
        installedSize = try c.decodeIfPresent(Int64.self, forKey: .installedSize)
        releaseNotes = try c.decodeIfPresent(String.self, forKey: .releaseNotes)
        // A bad screenshot list never costs the app its entry.
        shots = (try? c.decodeIfPresent(LossyShots.self, forKey: .shots))?.shots ?? []
        shotsVersion = try? c.decodeIfPresent(String.self, forKey: .shotsVersion)
    }

    private static func resolve(_ decoder: any Decoder) -> (String) -> URL? {
        let base = decoder.userInfo[FeedParser.baseURLKey] as? URL
        return { URL(string: $0, relativeTo: base)?.absoluteURL }
    }

    /// Everything an install needs is present and well-formed.
    public var isInstallable: Bool {
        guard let version, !version.isEmpty, let bundleId, !bundleId.isEmpty, downloadUrl != nil,
              let sha256, sha256.count == 64, sha256.allSatisfy(\.isHexDigit)
        else { return false }
        return status != "planned"
    }

    /// The launcher itself.
    public var isHub: Bool { hub == true }

    /// "An open alternative to Paste" / "... to Squash and PDF Squeezer".
    public var alternativeText: String? {
        guard !replaces.isEmpty else { return nil }
        return "An open alternative to \(ListFormat.and(replaces))."
    }
}

public enum ListFormat {
    /// "A", "A and B", "A, B and C".
    public static func and(_ items: [String]) -> String {
        switch items.count {
        case 0: ""
        case 1: items[0]
        default: items.dropLast().joined(separator: ", ") + " and " + items.last!
        }
    }
}

public enum FeedError: Error, Equatable, Sendable {
    case unreadable
    case unsupportedSchema(Int)

    public var message: String {
        switch self {
        case .unreadable:
            "The app catalog couldn't be read. Try again later."
        case .unsupportedSchema:
            "This catalog needs a newer version of Slopapp. Download the latest version from the Slopapp website."
        }
    }
}

public enum FeedParser {
    static let baseURLKey = CodingUserInfoKey(rawValue: "app.slopapp.feedBaseURL")!

    /// Parses feed JSON. Relative URLs resolve against `baseURL` (the feed's own URL).
    /// Entries that are malformed are dropped instead of failing the whole feed.
    public static func parse(_ data: Data, baseURL: URL?) throws -> Feed {
        struct Header: Decodable { var schemaVersion: Int? }
        struct LossyApps: Decodable {
            var apps: [FeedApp]
            init(from decoder: any Decoder) throws {
                enum Keys: String, CodingKey { case apps }
                var list = try decoder.container(keyedBy: Keys.self).nestedUnkeyedContainer(forKey: .apps)
                var apps: [FeedApp] = []
                while !list.isAtEnd {
                    if let app = try? list.decode(FeedApp.self) {
                        apps.append(app)
                    } else {
                        _ = try? list.decode(Skip.self)
                    }
                }
                self.apps = apps
            }
            struct Skip: Decodable {}
        }
        struct Dates: Decodable { var generatedAt: Date? }

        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .custom { decoder in
            let text = try decoder.singleValueContainer().decode(String.self)
            let formatter = ISO8601DateFormatter()
            formatter.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
            if let date = formatter.date(from: text) { return date }
            formatter.formatOptions = [.withInternetDateTime]
            if let date = formatter.date(from: text) { return date }
            throw DecodingError.dataCorruptedError(in: try decoder.singleValueContainer(), debugDescription: "bad date")
        }
        if let baseURL { decoder.userInfo[baseURLKey] = baseURL }

        guard let header = try? decoder.decode(Header.self, from: data) else { throw FeedError.unreadable }
        let schema = header.schemaVersion ?? 1
        guard schema <= Feed.supportedSchema else { throw FeedError.unsupportedSchema(schema) }
        guard let apps = try? decoder.decode(LossyApps.self, from: data) else { throw FeedError.unreadable }
        let generatedAt = (try? decoder.decode(Dates.self, from: data))?.generatedAt
        // Slugs must be unique; keep the first.
        var seen = Set<String>()
        let unique = apps.apps.filter { seen.insert($0.slug).inserted }
        return Feed(schemaVersion: schema, generatedAt: generatedAt, apps: unique)
    }
}
